CREATE TABLE IF NOT EXISTS richo_release_attestations_l2(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),artifact_digest text NOT NULL,commit_sha text NOT NULL,repository text NOT NULL,builder text NOT NULL,tests_digest text NOT NULL,dependencies jsonb NOT NULL DEFAULT '[]'::jsonb,attestation_digest text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_release_evidence_packages_l2(id uuid PRIMARY KEY,version text NOT NULL,attestation jsonb NOT NULL,gates jsonb NOT NULL,parity jsonb NOT NULL,risk jsonb NOT NULL,impact jsonb NOT NULL,rollout jsonb NOT NULL,digest text NOT NULL UNIQUE,immutable boolean NOT NULL DEFAULT true,correlation_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_release_rollout_observations_l2(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),release_version text NOT NULL,stage_pct numeric(6,3) NOT NULL,metrics jsonb NOT NULL,decision text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_environment_parity_l2(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),environment text NOT NULL,score numeric(6,2) NOT NULL,differences jsonb NOT NULL DEFAULT '[]'::jsonb,passed boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
